import{_,c as a,o as t,a4 as e}from"./chunks/framework.4aTu-Nia.js";const p=JSON.parse('{"title":"如何停止胡思乱想【告别精神内耗，成为一个快乐的人！美国心理协会反焦虑思维训练课，心理学博士30年执业经验精华，专治敏感、自我否定、精神...","description":"","frontmatter":{"kindle-sync":{"bookId":"32567","title":"如何停止胡思乱想【告别精神内耗，成为一个快乐的人！美国心理协会反焦虑思维训练课，心理学博士30年执业经验精华，专治敏感、自我否定、精神... (z-lib.org)","author":"【美】卡罗尔·克肖 【美】比尔·韦德","highlightsCount":3}},"headers":[],"relativePath":"books/【美】比尔·韦德-如何停止胡思乱想【告别精神内耗，成为一个快乐的人！美国心理协会反焦虑思维训练课，心理学博士30年执业经验精华，专治敏感、自我否定、精神.md","filePath":"books/【美】比尔·韦德-如何停止胡思乱想【告别精神内耗，成为一个快乐的人！美国心理协会反焦虑思维训练课，心理学博士30年执业经验精华，专治敏感、自我否定、精神.md"}'),o={name:"books/【美】比尔·韦德-如何停止胡思乱想【告别精神内耗，成为一个快乐的人！美国心理协会反焦虑思维训练课，心理学博士30年执业经验精华，专治敏感、自我否定、精神.md"},r=e('<h1 id="如何停止胡思乱想【告别精神内耗-成为一个快乐的人-美国心理协会反焦虑思维训练课-心理学博士30年执业经验精华-专治敏感、自我否定、精神" tabindex="-1">如何停止胡思乱想【告别精神内耗，成为一个快乐的人！美国心理协会反焦虑思维训练课，心理学博士30年执业经验精华，专治敏感、自我否定、精神... <a class="header-anchor" href="#如何停止胡思乱想【告别精神内耗-成为一个快乐的人-美国心理协会反焦虑思维训练课-心理学博士30年执业经验精华-专治敏感、自我否定、精神" aria-label="Permalink to &quot;如何停止胡思乱想【告别精神内耗，成为一个快乐的人！美国心理协会反焦虑思维训练课，心理学博士30年执业经验精华，专治敏感、自我否定、精神...&quot;">​</a></h1><h2 id="metadata" tabindex="-1">Metadata <a class="header-anchor" href="#metadata" aria-label="Permalink to &quot;Metadata&quot;">​</a></h2><ul><li>Author: [[【美】卡罗尔·克肖 【美】比尔·韦德]]</li></ul><h2 id="highlights" tabindex="-1">Highlights <a class="header-anchor" href="#highlights" aria-label="Permalink to &quot;Highlights&quot;">​</a></h2><p>普遍认同催眠可以给我们带来： 1. 将注意力的范围从“宽泛”转变成“狭窄”，最后变成高度集中； 2. 运用记忆和想象； 3. 自觉行为变成自动行为。 — location: <a href="./.html">2324</a> ^ref-14655</p><hr><p>关键是，你需要泡个澡或在公园散会儿步，让头脑平静下来，从而使自己跳出习惯性的思维模式。当你运用这个办法的时候，就能避开焦虑的干扰，就不会强迫性地想要某些事情发生。大脑会给你很多好的点子，让你顺利解决大部分的难题。 — location: <a href="./.html">2372</a> ^ref-49686</p><hr><p>学会中断焦虑思维，运用神经链建立新的关联，通过全新的理解和“将神经再次模式化”的练习来调节新的大脑思维状态，进入全脑同步运作状态，最终触发心流，创造一个全新的自己。 — location: <a href="./.html">2423</a> ^ref-17060</p><hr>',10),h=[r];function i(l,s,n,c,d,f){return t(),a("div",null,h)}const u=_(o,[["render",i]]);export{p as __pageData,u as default};
